package com.nigson.experience.careers;
import java.util.*;import java.time.Instant;import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.web.bind.annotation.*;import tools.jackson.databind.JsonNode;import com.nigson.shared.events.EventCodec;import com.nigson.shared.problem.ApiValues;import com.nigson.shared.problem.*;import com.nigson.shared.security.PrivateWorkload;
@RestController
public final class CareerController {
 private final CareerService service;public CareerController(CareerService service){this.service=service;}
 private PrivateWorkload.Proof proof(){var a=SecurityContextHolder.getContext().getAuthentication();if(a==null||!a.isAuthenticated())throw new Problem.Failure(ProblemCode.AUTH_REQUIRED);if(!(a.getPrincipal() instanceof PrivateWorkload.Proof p))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);return p;}
 private static String header(HttpServletRequest r,String name){var v=Collections.list(r.getHeaders(name));if(v.size()!=1||v.getFirst().isBlank()||v.getFirst().length()>100)throw ApiValues.invalid();return ApiValues.idempotencyKey(v.getFirst());}
 private static UUID correlation(){var c=com.nigson.shared.observability.WireContext.current();return c==null?com.nigson.shared.observability.WireContext.correlation(null):c.correlationId;}
 private static void fields(JsonNode body,Set<String> required,Set<String> optional){Set<String> allowed=new HashSet<>(required);allowed.addAll(optional);if(body==null||!body.isObject()||!body.propertyNames().containsAll(required)||!allowed.containsAll(body.propertyNames()))throw ApiValues.invalid();}
 private static String string(JsonNode body,String name){JsonNode n=body.get(name);if(n==null||!n.isString())throw ApiValues.invalid();return n.asString();}
 private static CareerValues.OpportunityInput opportunity(JsonNode b){Set<String> req=Set.of("title","slug","kind","description","fieldsSchema","state"),opt=Set.of("closesAt");fields(b,req,opt);Instant closes=null;if(b.has("closesAt")&&!b.get("closesAt").isNull()){if(!b.path("closesAt").isString())throw ApiValues.invalid();closes=ApiValues.instant(b.path("closesAt").asString());}return new CareerValues.OpportunityInput(string(b,"title"),string(b,"slug"),string(b,"kind"),string(b,"description"),b.get("fieldsSchema"),closes,string(b,"state"));}
 private static CareerValues.Submission submission(JsonNode b){Set<String> req=Set.of("name","email","answers","privacyPolicyVersion","antiSpamToken"),opt=Set.of("cvFileId");fields(b,req,opt);UUID file=null;if(b.has("cvFileId")&&!b.get("cvFileId").isNull()){if(!b.path("cvFileId").isString())throw ApiValues.invalid();file=ApiValues.uuid(b.path("cvFileId").asString());}return new CareerValues.Submission(string(b,"name"),string(b,"email"),b.get("answers"),file,string(b,"privacyPolicyVersion"),string(b,"antiSpamToken"));}
 private static CareerValues.Transition transition(JsonNode b){Set<String> exact=Set.of("state","reason");fields(b,exact,Set.of());return new CareerValues.Transition(string(b,"state"),string(b,"reason"));}
 private static void query(HttpServletRequest r,Set<String> allowed){var map=new HashMap<String,String>();r.getParameterMap().forEach((k,v)->{if(v==null||v.length!=1)throw ApiValues.invalid();map.put(k,v[0]);});ApiValues.query(map,allowed);}
 @GetMapping(value="/api/v1/career-opportunities",produces=MediaType.APPLICATION_JSON_VALUE) public ResponseEntity<CareerService.Page<CareerService.Opportunity>> opportunities(HttpServletRequest r,@RequestParam(required=false)String kind,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="createdAt,desc")String sort){if(r.getContentLengthLong()>0)throw ApiValues.invalid();query(r,Set.of("kind","page","size","sort"));return ResponseEntity.ok().header("Cache-Control","public, max-age=30").body(service.publicOpportunities(kind,page,size,sort));}
 @PostMapping(value="/api/v1/staff/career-opportunities",consumes=MediaType.APPLICATION_JSON_VALUE,produces=MediaType.APPLICATION_JSON_VALUE) public ResponseEntity<CareerService.Opportunity> create(HttpServletRequest r,@RequestBody JsonNode body){query(r,Set.of());return ResponseEntity.status(201).header("Cache-Control","no-store").body(service.create(proof(),opportunity(body),header(r,"Idempotency-Key"),correlation()));}
 @PostMapping(value="/api/v1/career-opportunities/{id}/applications",consumes=MediaType.APPLICATION_JSON_VALUE,produces=MediaType.APPLICATION_JSON_VALUE) public ResponseEntity<CareerService.Created> submit(HttpServletRequest r,@PathVariable String id,@RequestBody JsonNode body){query(r,Set.of());var tokenHeaders=Collections.list(r.getHeaders("X-Career-Upload-Token"));if(tokenHeaders.size()>1)throw ApiValues.invalid();String uploadToken=tokenHeaders.isEmpty()?null:tokenHeaders.getFirst();if(uploadToken!=null&&(uploadToken.isBlank()||uploadToken.length()>512))throw ApiValues.invalid();var input=submission(body);if((input.cvFileId()!=null)!=(uploadToken!=null))throw ApiValues.invalid();var result=service.submit(ApiValues.uuid(id),input,uploadToken,header(r,"Idempotency-Key"),correlation());return ResponseEntity.status(201).header("Cache-Control","no-store").body(result);}
 @GetMapping(value="/api/v1/staff/career-applications",produces=MediaType.APPLICATION_JSON_VALUE) public ResponseEntity<CareerService.Page<CareerService.Summary>> list(HttpServletRequest r,@RequestParam(required=false)String opportunityId,@RequestParam(required=false)String state,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="createdAt,desc")String sort){query(r,Set.of("opportunityId","state","page","size","sort"));return ResponseEntity.ok().header("Cache-Control","no-store").body(service.list(proof(),opportunityId==null?null:ApiValues.uuid(opportunityId),state,page,size,sort));}
 @GetMapping(value="/api/v1/staff/career-applications/{id}",produces=MediaType.APPLICATION_JSON_VALUE) public ResponseEntity<CareerService.Application> detail(HttpServletRequest r,@PathVariable String id){if(!r.getParameterMap().isEmpty()||r.getContentLengthLong()>0)throw ApiValues.invalid();return ResponseEntity.ok().header("Cache-Control","no-store").body(service.detail(proof(),ApiValues.uuid(id),correlation()));}
 @PatchMapping(value="/api/v1/staff/career-applications/{id}",consumes=MediaType.APPLICATION_JSON_VALUE,produces=MediaType.APPLICATION_JSON_VALUE) public ResponseEntity<CareerService.Changed> transition(HttpServletRequest r,@PathVariable String id,@RequestBody JsonNode body){query(r,Set.of());String match=header(r,"If-Match");if(!match.matches("\"[0-9]+\""))throw ApiValues.invalid();long expected;try{expected=Long.parseLong(match.substring(1,match.length()-1));}catch(Exception e){throw ApiValues.invalid();}return ResponseEntity.ok().header("Cache-Control","no-store").body(service.transition(proof(),ApiValues.uuid(id),transition(body),expected,header(r,"Idempotency-Key"),correlation()));}
 @GetMapping(value="/internal/v1/career-applications/{id}/sheet-context",produces=MediaType.APPLICATION_JSON_VALUE) public ResponseEntity<CareerService.SheetContext> sheet(HttpServletRequest r,@PathVariable String id){if(!r.getParameterMap().isEmpty()||r.getContentLengthLong()>0)throw ApiValues.invalid();return ResponseEntity.ok().header("Cache-Control","no-store").body(service.sheet(proof(),ApiValues.uuid(id),correlation()));}
}
